import { PlaneGeometry, Mesh, MeshStandardNodeMaterial, Color } from 'three/webgpu';
import { texture, uv, vec2, vec3, vec4, uniform, mix, float, mul, add, sub, sin, positionLocal } from 'three/tsl';

export default function createNode(config, ctx) {
  const width = 1.6;
  const height = 1.0;

  const geometry = new PlaneGeometry(width, height, 1, 1);
  const material = new MeshStandardNodeMaterial();
  material.metalness = 0.35;
  material.roughness = 0.6;

  let map = null;
  const imageUrl = '/prism-mock/home/nodes/orb-decor.png';
  if (imageUrl && ctx.textureLoader) {
    map = ctx.textureLoader.load(imageUrl);
  }

  const inkColor = uniform(new Color('#16161d'));
  const surfaceColor = uniform(new Color('#0b0b10'));
  const accentColor = uniform(new Color('#ff2a38'));

  const vUv = uv();

  // engineered gradient surface (linear-ish diagonal gradient, no soft blur)
  const gradientT = add(mul(vUv.x, 0.6), mul(vUv.y, 0.4));
  const baseGradient = mix(surfaceColor, inkColor, gradientT);

  // subtle grain via high-frequency sine noise pattern
  const grainFreq = 400.0;
  const grainA = sin(mul(vUv.x, grainFreq));
  const grainB = sin(mul(vUv.y, grainFreq * 1.37));
  const grain = mul(mul(grainA, grainB), 0.015);

  let colorNode = add(baseGradient, vec3(grain, grain, grain));

  if (map) {
    const texColor = texture(map, vUv);
    colorNode = mix(colorNode, texColor.rgb, texColor.a);
  }

  // thin accent edge line at bottom of card for engineered feel
  const edgeMask = sub(1.0, vUv.y).greaterThan(float(0.97));
  colorNode = mix(colorNode, accentColor, mul(float(edgeMask), 0.6));

  material.colorNode = colorNode;

  const mesh = new Mesh(geometry, material);
  mesh.position.set(-3.2, -0.3, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
  };

  return mesh;
}
